*{box-sizing:border-box}body{background:#f3f6fb}.verifier-content{padding:20px;flex:1;min-height:0;overflow:hidden;display:flex;flex-direction:column}.page-header-card{background:white;border:1px solid #d6dce8;border-radius:10px;padding:18px 20px;margin-bottom:16px}.page-header-card h1{margin:0;font-size:24px;color:#1f2937}.page-header-card p{margin:6px 0 0;font-size:14px;color:#6b7280}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:14px;flex-wrap:wrap}.search-box{width:320px;max-width:100%;padding:10px 12px;border:1px solid #cbd5e1;border-radius:8px;font-size:14px}.back-link{text-decoration:none;background:#374151;color:white;padding:10px 14px;border-radius:8px;font-size:14px;display:inline-flex;align-items:center;gap:6px}.sheet-card{background:white;border:1px solid #cbd5e1;border-radius:10px;overflow:hidden;flex:1;min-height:0;display:flex;flex-direction:column}.table-scroll{width:100%;overflow:auto;flex:1;min-height:0}.verifier-table{width:100%;min-width:2200px;border-collapse:collapse;font-size:13px}.verifier-table th{background:#dbeafe;color:#111827;font-weight:bold;text-align:center;border:1px solid #b6c3d5;padding:10px 8px;white-space:nowrap;position:sticky;top:0;z-index:3}.verifier-table td{border:1px solid #d1d5db;padding:9px 8px;white-space:nowrap;vertical-align:middle;background:white;text-align:center}.verifier-table tbody tr:nth-child(even) td{background:#f9fafb}.verifier-table tbody tr:hover td{background:#eef6ff}.row-priority td{background:#fff7ed!important}.priority-label{display:inline-block;background:#fed7aa;color:#9a3412;padding:3px 8px;border-radius:999px;font-size:11px;font-weight:800;margin-left:6px}.queue-number{font-weight:bold;color:#1d4ed8}.priority-queue-number{color:#c2410c!important}.status-badge{display:inline-block;min-width:125px;text-align:center;padding:6px 10px;border-radius:999px;font-size:12px;font-weight:bold}.status-step-2{background:#fef3c7;color:#92400e}.status-called-2{background:#fde68a;color:#78350f}.status-step-3{background:#dbeafe;color:#1e40af}.status-called-3{background:#bfdbfe;color:#1e3a8a}.status-paid{background:#dcfce7;color:#166534}.status-none{background:#e5e7eb;color:#374151}.elig-eligible{background:#dcfce7;color:#166534}.elig-pending{background:#fef3c7;color:#92400e}.elig-not{background:#fee2e2;color:#991b1b}.action-group{display:flex;gap:6px;justify-content:center;flex-wrap:wrap}.action-group form{margin:0}.action-btn{border:none;border-radius:6px;padding:8px 10px;font-size:12px;color:white;cursor:pointer;white-space:nowrap;font-weight:700;text-decoration:none;display:inline-block}.btn-form{background:#2563eb}.btn-regular{background:#16a34a}.btn-priority{background:#dc2626}.btn-regenerate{background:#f97316}.action-btn:disabled{background:#9ca3af;cursor:not-allowed}.footer-note{padding:10px 12px;font-size:12px;color:#6b7280;background:#f9fafb;border-top:1px solid #d1d5db;display:flex;justify-content:space-between}.empty-state,.loading-text{text-align:center;padding:20px;color:#6b7280;font-weight:bold}.modal-overlay{display:none;position:fixed;inset:0;background:rgba(15,23,42,.55);z-index:9999;justify-content:center;align-items:center}.modal-box{width:360px;max-width:90%;background:#fff;border-radius:14px;padding:24px;text-align:center;box-shadow:0 14px 40px rgba(0,0,0,.25)}.modal-actions{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:14px}.modal-btn{height:46px;border:none;border-radius:10px;color:white;font-weight:700;cursor:pointer;font-size:15px}.pal-btn{background:#16a34a}.prio-btn{background:#dc2626}.modal-cancel{width:100%;height:42px;border:none;border-radius:10px;background:#e5e7eb;color:#111827;font-weight:700;cursor:pointer}
