</div>
<div id="regenerateModal" class="modal-overlay"><div class="modal-box"><h2>Choose Queue Type</h2><p>Select the new queue type for this beneficiary.</p><form id="regenerateForm" method="POST" action="../api/regenerate_qn.php"><input type="hidden" name="beneficiary_id" id="regenBeneficiaryId"><input type="hidden" name="new_queue_type" id="regenQueueType"><div class="modal-actions"><button type="button" class="modal-btn pal-btn" onclick="submitRegenerate('PAL')">PAL</button><button type="button" class="modal-btn prio-btn" onclick="submitRegenerate('PRIO')">PRIO</button></div><button type="button" class="modal-cancel" onclick="closeRegenerateModal()">Cancel</button></form></div></div>
<script>
const searchInput=document.getElementById('searchInput');

  const tableBody=document.getElementById('beneficiaryRows');
  const lastUpdated=document.getElementById('lastUpdated');
  let beneficiaries=[];
  
function escapeHTML(value){if(value===null||value===undefined)return'';return String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;')}
  
function displayStatus(status){if(status==='WAITING_STEP_2')
  return'WAITING: STEP 2';if(status==='CALLED_STEP_2')
  return'CALLED: STEP 2';if(status==='WAITING_STEP_3')return'WAITING: STEP 3';if(status==='CALLED_STEP_3')return'CALLED: STEP 3';if(status==='PAID')return'PAID';return'NO QUEUE NUMBER'}
function statusClass(status){if(status==='WAITING_STEP_2')return'status-step-2';if(status==='CALLED_STEP_2')return'status-called-2';if(status==='WAITING_STEP_3')return'status-step-3';if(status==='CALLED_STEP_3')return'status-called-3';if(status==='PAID')return'status-paid';return'status-none'}
function eligibilityClass(status){if(status==='Eligible')return'elig-eligible';if(status==='Not Eligible')return'elig-not';return'elig-pending'}
function openRegenerateModal(id){document.getElementById('regenBeneficiaryId').value=id;document.getElementById('regenQueueType').value='';document.getElementById('regenerateModal').style.display='flex'}
function closeRegenerateModal(){document.getElementById('regenerateModal').style.display='none'}
function submitRegenerate(type){if(type!=='PAL'&&type!=='PRIO'){alert('Invalid queue type.');return}if(!confirm('Regenerate queue number as '+type+'?'))return;document.getElementById('regenQueueType').value=type;document.getElementById('regenerateForm').submit()}
function renderTable(){const searchValue=searchInput.value.toLowerCase();const filtered=beneficiaries.filter(row=>Object.values(row).some(value=>String(value??'').toLowerCase().includes(searchValue)));if(filtered.length===0){tableBody.innerHTML='<tr><td colspan="18" class="empty-state">No beneficiaries found.</td></tr>';return}let html='';filtered.forEach((row,index)=>{const hasQueue=row.queue_number&&row.queue_number!=='';const isPriority=row.queue_type==='priority';const isEligible=row.eligibility_status==='Eligible';const birthday=row.birthday_month&&row.birthday_day&&row.birthday_year?`${row.birthday_month}/${row.birthday_day}/${row.birthday_year}`:'';const qClass=isPriority?'queue-number priority-queue-number':'queue-number';const prio=isPriority?'<span class="priority-label">PRIO</span>':'';html+=`<tr class="${isPriority?'row-priority':''}"><td>${index+1}</td><td>${escapeHTML(row.last_name)}</td><td>${escapeHTML(row.first_name)}</td><td>${escapeHTML(row.middle_name)}</td><td>${escapeHTML(row.ext_name)}</td><td>${escapeHTML(row.region)}</td><td>${escapeHTML(row.province)}</td><td>${escapeHTML(row.city_municipality)}</td><td>${escapeHTML(row.barangay)}</td><td>${escapeHTML(row.contact_number)}</td><td>${escapeHTML(birthday)}</td><td>${escapeHTML(row.age)}</td><td>${escapeHTML(row.sex)}</td><td>${escapeHTML(row.lgu)}</td><td><span class="status-badge ${eligibilityClass(row.eligibility_status)}">${escapeHTML(row.eligibility_status)}</span></td><td class="${qClass}">${hasQueue?escapeHTML(row.queue_number)+prio:'Not generated'}</td><td><span class="status-badge ${statusClass(row.workflow_status)}">${displayStatus(row.workflow_status)}</span></td><td><div class="action-group"><a href="eligibility_form.php?beneficiary_id=${escapeHTML(row.id)}" class="action-btn btn-form">Eligibility Form</a><form method="POST" action="../api/generate_regular_qn.php" onsubmit="return confirm('Generate regular queue number?');"><input type="hidden" name="beneficiary_id" value="${escapeHTML(row.id)}"><button type="submit" class="action-btn btn-regular" ${hasQueue||!isEligible?'disabled':''}>Generate Regular QN</button></form><form method="POST" action="../api/generate_priority_qn.php" onsubmit="return confirm('Generate priority queue number?');"><input type="hidden" name="beneficiary_id" value="${escapeHTML(row.id)}"><button type="submit" class="action-btn btn-priority" ${hasQueue||!isEligible?'disabled':''}>Generate Priority QN</button></form><button type="button" class="action-btn btn-regenerate" onclick="openRegenerateModal('${escapeHTML(row.id)}')" ${!hasQueue?'disabled':''}>Regenerate QN</button></div></td></tr>`});tableBody.innerHTML=html}
async function loadVerifierData(){try{const response=await fetch('../api/verifier_data.php');const data=await response.json();if(!data.success){tableBody.innerHTML=`<tr><td colspan="18" class="empty-state">${escapeHTML(data.message)}</td></tr>`;return}beneficiaries=data.beneficiaries;renderTable();lastUpdated.innerText='Last updated: '+new Date().toLocaleTimeString()}catch(error){tableBody.innerHTML='<tr><td colspan="18" class="empty-state">Failed to load data.</td></tr>'}}
searchInput.addEventListener('input',renderTable);loadVerifierData();setInterval(loadVerifierData,3000);
</script>
</body>
</html>
